package com.example.acres.entity;
import jakarta.persistence.*; import lombok.*; import java.math.*; import java.time.*;
@Entity @Table(name="sales", indexes={@Index(name="idx_sales_user",columnList="user_id"),@Index(name="idx_sales_date",columnList="sale_date")}) @Getter @Setter @NoArgsConstructor
public class Sale { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id") private User user; @Column(nullable=false,precision=12,scale=4) private BigDecimal acres; @Column(name="sale_date",nullable=false) private LocalDate saleDate; private String buyerName; private String plotReference; @Column(columnDefinition="text") private String notes; @Column(nullable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="created_by") private User createdBy; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="updated_by") private User updatedBy; @PrePersist void pre(){createdAt=updatedAt=Instant.now();} @PreUpdate void upd(){updatedAt=Instant.now();} }
